command:
printf '%s
' '--- package ---'; dpkg-query -W -f='Package=${Package}
Version=${Version}
Architecture=${Architecture}
Maintainer=${Maintainer}
Homepage=${Homepage}
Description=${Description}
' chatgpt 2>/dev/null || true; printf '%s
' '--- apt policy ---'; apt-cache policy chatgpt 2>/dev/null || true; printf '%s
' '--- desktop ---'; sed -n '1,160p' /usr/share/applications/chatgpt.desktop 2>/dev/null || true; printf '%s
' '--- local starter ---'; sed -n '1,200p' ~/.local/share/applications/chatgpt-10x-starter.desktop 2>/dev/null || true; printf '%s
' '--- processes ---'; ps -eo pid=,ppid=,comm=,args= | grep -Ei '[c]hatgpt|[c]odex' | head -n 50 || true
